import {captureContext,restoreContext,numericInvalid} from './cinematic-studio-ui.js?v=directorcinematic01';
import {$,esc,option} from './ui.js';
import {sceneSpan,defaultWindow,validWindow,windowRange} from './cinematic-timing.js?v=directorcinematic01';
import {defaultCamera,lightingProfile,validLighting,LIGHT_PROFILES} from './cinematic-direction-model.js?v=directorcinematic01';
import {lightEvent} from './cinematic-light-model.js?v=directorcinematic01';
export const num=(label,key,value,min,max,step='any')=>`<label class="field"><span>${label}</span><input data-direction-value="${key}" type="number" required value="${Number(value.toFixed(6))}" min="${min}" max="${max}" step="${step}"></label>`;
const check=(label,key,value)=>`<label class="check-field"><input data-direction-value="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;
function report(root,change,state,message){root.dataset.directionInvalid='true';$('[data-direction-error]',root).textContent=message;change(state);}
function accept(root,change,state){delete root.dataset.directionInvalid;$('[data-direction-error]',root).textContent='';change(state);}
export function renderWindows(root,{state,composer,change,span,legacySpan}){
  const targets=[];const add=(label,target,camera=false)=>{if(target)targets.push({label,target,camera});};
  add('Movimento da câmera',state.camera,true);add('Instabilidade global',state.camera?.instability);
  add('Iluminação ambiente',state.lighting);for(const [i,s] of (state.lighting?.spots??[]).entries())add('Luz '+(i+1),s);
  add('Fundo vivo (vídeo)',state.backgroundVideo);
  for(const layer of composer.layers){add('Visibilidade · '+layer.name,layer);for(const fx of layer.effects??[])add(layer.name+' · '+fx.type,fx);if(layer.video)add(layer.name+' · vídeo',layer.video);}
  const context=captureContext(root),invalidGroups=new Set();
  root.innerHTML=`<h3>Direção temporal</h3><p class="form-hint">Movimento e vida da cena são independentes. O comportamento antigo é mantido até você definir uma janela.</p>${check('Duração de cena independente','independent',state.sceneDuration!==undefined)}${num('Duração total da cena antes da saída (s)','duration',span,3,180)}<p class="form-hint">Sem duração independente: movimento + permanência (${legacySpan} s). Cada janela pode abranger a cena inteira ou um intervalo em segundos. Repetição e velocidade ficam no FX, luz ou vídeo.</p><div class="cinematic-window-list">${targets.map(({label,target,camera},i)=>{const w=target.window,r=windowRange(w,span);return `<details data-window-label="${esc(label)}" ${i<2?'open':''}><summary>${esc(label)} · ${w?w.mode==='scene'?'cena inteira':w.start+'–'+w.end+' s':'legado'}</summary><div class="cinematic-window-bar"><span style="left:${r.start/span*100}%;width:${Math.max(0,r.end-r.start)/span*100}%"></span></div><label><input type="checkbox" data-window-enable="${i}" ${w?'checked':''}>Definir janela</label>${w?`<label class="field">Escopo<select data-window-mode="${i}">${option('scene','Cena inteira',w.mode==='scene')}${option('range','Intervalo',w.mode==='range')}</select></label><div class="cinematic-form-grid">${['start','end',...(camera?[]:['fadeIn','fadeOut'])].map(k=>`<label class="field"><span>${({start:'Início',end:'Fim',fadeIn:'Entrada',fadeOut:'Saída'})[k]} (s)</span><input type="number" required data-window-field="${i}.${k}" value="${w[k]}" min="0" max="180" step="any" ${w.mode==='scene'&&['start','end'].includes(k)?'disabled':''}></label>`).join('')}</div>`:''}${camera?'<p class="form-hint">A câmera mantém o enquadramento final após o trecho. A suavização vem das curvas do caminho.</p>':''}</details>`;}).join('')}</div><p data-direction-error class="form-error" role="status"></p>`;
  restoreContext(root,context);
  const render=()=>renderWindows(root,{state,composer,change,span:state.sceneDuration??legacySpan,legacySpan});
  const commit=()=>{if(invalidGroups.size||numericInvalid(root))return report(root,change,state,'Confira o intervalo indicado. O último valor válido foi preservado.');accept(root,change,state);};
  const bars=()=>{const duration=state.sceneDuration??legacySpan;for(const [i,t] of targets.entries()){const d=root.querySelector('[data-window-label="'+CSS.escape(t.label)+'"]'),r=windowRange(t.target.window,duration);if(!d)continue;const bar=d.querySelector('.cinematic-window-bar span');bar.style.left=r.start/duration*100+'%';bar.style.width=Math.max(0,r.end-r.start)/duration*100+'%';d.querySelector('summary').textContent=t.label+' · '+(t.target.window?(t.target.window.mode==='scene'?'cena inteira':r.start+'–'+r.end+' s'):'legado');}};
  $('[data-direction-value=independent]',root).onchange=e=>{if(e.target.checked)state.sceneDuration=span;else delete state.sceneDuration;accept(root,change,state);render();};
  const durationInput=$('[data-direction-value=duration]',root);durationInput.onchange=durationInput.oninput=e=>{if(!e.target.validity.valid)return report(root,change,state,'Use uma duração entre 3 e 180 segundos.');state.sceneDuration=Number(e.target.value);commit();bars();};
  for(const input of root.querySelectorAll('[data-window-enable]'))input.onchange=()=>{const t=targets[Number(input.dataset.windowEnable)];if(input.checked){t.target.window=defaultWindow(state.sceneDuration??legacySpan);if(t.target===state.camera?.instability){t.target.start=0;t.target.end=1;t.target.window.fadeIn=t.target.fadeIn*span;t.target.window.fadeOut=t.target.fadeOut*span;}}else delete t.target.window;accept(root,change,state);render();};
  for(const input of root.querySelectorAll('[data-window-mode]'))input.onchange=()=>{targets[Number(input.dataset.windowMode)].target.window.mode=input.value;accept(root,change,state);render();};
  for(const input of root.querySelectorAll('[data-window-field]'))input.onchange=input.oninput=()=>{const [i]=input.dataset.windowField.split('.'),t=targets[Number(i)],w={...t.target.window};for(const n of root.querySelectorAll('[data-window-field^="'+i+'."]'))w[n.dataset.windowField.split('.')[1]]=Number(n.value);
    if([...root.querySelectorAll('[data-window-field^="'+i+'."]')].some(n=>!n.validity.valid)||!validWindow(w)){invalidGroups.add(i);return report(root,change,state,'Use início antes do fim e entradas/saídas que caibam no intervalo.');}
    invalidGroups.delete(i);t.target.window=w;commit();bars();};
}
export function renderLights(root,{state,change}){
  const light=state.lighting??lightingProfile();
  root.innerHTML=`${check('Iluminação independente','enabled',!!state.lighting?.enabled)}<label class="field">Perfil<select data-light-profile><option value="">Personalizado</option>${Object.entries(LIGHT_PROFILES).map(([id,label])=>option(id,label)).join('')}</select></label><label class="field">Cor ambiente<input type="color" data-light-field="color" value="${light.color}"></label>${num('Luz ambiente','intensity',light.intensity,0,.8)}${num('Escurecer','darkness',light.darkness,0,.85)}${num('Vinheta','vignette',light.vignette,0,.9)}<label><input type="checkbox" data-ambient-flicker ${light.flicker?'checked':''}>Flicker ambiente suave</label><p class="form-hint">Janelas e fades ficam em Direção. Até quatro luzes e oito eventos; flashes limitados para conforto visual.</p>${light.spots.map((s,i)=>`<details open><summary>Luz ${i+1}</summary><label>Tipo<select data-spot-kind="${i}">${['spot','beam','global'].map(k=>option(k,({spot:'Spot circular',beam:'Feixe teatral',global:'Luz global'})[k],(s.kind??'spot')===k)).join('')}</select></label><label><input type="checkbox" data-spot-enable="${i}" ${s.enabled?'checked':''}>Ativa</label><input aria-label="Cor luz ${i+1}" type="color" data-light-field="spots.${i}.color" value="${s.color}"><div class="cinematic-form-grid">${['x','y','intensity','radius','softness','rotation','pulse','seconds'].map(k=>num(({x:'X',y:'Y',intensity:'Intensidade',radius:'Raio/alcance',softness:'Suavidade',rotation:'Rotação',pulse:'Pulso',seconds:'Período (s)'})[k],`spots.${i}.${k}`,s[k]??0,k==='rotation'?-180:k==='seconds'?2:k==='softness'?.1:k==='radius'?.05:0,k==='rotation'?180:k==='seconds'?20:k==='pulse'?.2:['radius','intensity'].includes(k)?.8:1)).join('')}</div><label><input type="checkbox" data-spot-flicker="${i}" ${s.flicker?'checked':''}>Flicker suave</label>${s.flicker?num('Flicker: intensidade',`spots.${i}.flicker.amount`,s.flicker.amount,0,.3)+num('Flicker: frequência (Hz)',`spots.${i}.flicker.frequency`,s.flicker.frequency,.1,2):''}<button type="button" data-remove-light="${i}">Excluir luz</button></details>`).join('')}<button type="button" data-add-light ${light.spots.length>=4?'disabled':''}>+ Luz</button><h3>Falhas de luz</h3>${(light.events??[]).map((e,i)=>`<details open><summary>${e.type==='blackout'?'Apagão':'Flash suave'} ${i+1}</summary><div class="cinematic-form-grid">${num('Início (s)',`events.${i}.start`,e.start,0,179)}${num('Duração (s)',`events.${i}.duration`,e.duration,.2,.5)}${num('Repetições',`events.${i}.count`,e.count,1,3,1)}${num('Distância entre inícios (s)',`events.${i}.gap`,e.gap,.6,10)}${num('Intensidade',`events.${i}.amount`,e.amount,0,e.type==='flash'?.25:1)}</div><button type="button" data-remove-event="${i}">Excluir evento</button></details>`).join('')}<div class="cinematic-actions"><button type="button" data-add-event="blackout">+ Apagão</button><button type="button" data-add-event="flash">+ Flash suave</button></div><p data-direction-error role="status" class="form-error"></p>`;
  const commit=(render=true)=>{if(!validLighting(light))return report(root,change,state,'Confira os limites das luzes e eventos.');state.lighting=light;accept(root,change,state);if(render)renderLights(root,{state,change});};
  $('[data-light-profile]',root).onchange=e=>{if(e.target.value){state.lighting=lightingProfile(e.target.value);accept(root,change,state);renderLights(root,{state,change});}};
  $('[data-add-light]',root).onclick=()=>{light.spots.push(lightingProfile().spots[0]);commit();};
  $('[data-ambient-flicker]',root).onchange=e=>{if(e.target.checked)light.flicker={amount:.15,frequency:.7,seed:41};else delete light.flicker;commit();};
  for(const n of root.querySelectorAll('[data-remove-light]'))n.onclick=()=>{light.spots.splice(Number(n.dataset.removeLight),1);commit();};
  for(const n of root.querySelectorAll('[data-spot-kind]'))n.onchange=()=>{light.spots[Number(n.dataset.spotKind)].kind=n.value;commit();};
  for(const n of root.querySelectorAll('[data-spot-enable]'))n.onchange=()=>{light.spots[Number(n.dataset.spotEnable)].enabled=n.checked;commit();};
  for(const n of root.querySelectorAll('[data-spot-flicker]'))n.onchange=()=>{const spot=light.spots[Number(n.dataset.spotFlicker)];if(n.checked)spot.flicker={amount:.15,frequency:.7,seed:37};else delete spot.flicker;commit();};
  for(const n of root.querySelectorAll('[data-add-event]'))n.onclick=()=>{light.events??=[];if(light.events.length>=8)return;light.events.push(lightEvent(n.dataset.addEvent));commit();};
  for(const n of root.querySelectorAll('[data-remove-event]'))n.onclick=()=>{light.events.splice(Number(n.dataset.removeEvent),1);commit();};
  for(const n of root.querySelectorAll('[data-direction-value],[data-light-field]'))n.onchange=()=>{if(!n.validity.valid)return report(root,change,state,'Valor fora dos limites.');const path=(n.dataset.directionValue??n.dataset.lightField).split('.');let target=light;for(const k of path.slice(0,-1))target=target[k];const key=path.at(-1),old=target[key];target[key]=n.type==='checkbox'?n.checked:n.type==='number'?Number(n.value):n.value;if(!validLighting(light)){target[key]=old;return report(root,change,state,'Valor inválido; a configuração anterior foi preservada.');}commit(false);};
  for(const n of root.querySelectorAll('input[type=number]'))n.oninput=n.onchange;
}
